{
 "cases": [
  {
   "name": "正常请求",
   "method": "POST",
   "path": "/v1/embeddings",
   "auth": "valid",
   "body": {
    "model": "embed-mini",
    "input": "Hello, world!"
   },
   "raw_body": null,
   "expect_status": 200,
   "expect_code": null
  },
  {
   "name": "非法 input (空字符串)",
   "method": "POST",
   "path": "/v1/embeddings",
   "auth": "valid",
   "body": {
    "model": "embed-mini",
    "input": ""
   },
   "raw_body": null,
   "expect_status": 400,
   "expect_code": "invalid_parameter"
  },
  {
   "name": "非法 input (空数组)",
   "method": "POST",
   "path": "/v1/embeddings",
   "auth": "valid",
   "body": {
    "model": "embed-mini",
    "input": []
   },
   "raw_body": null,
   "expect_status": 400,
   "expect_code": "invalid_parameter"
  },
  {
   "name": "模型类型不匹配",
   "method": "POST",
   "path": "/v1/embeddings",
   "auth": "valid",
   "body": {
    "model": "qwen-mini",
    "input": "Hello, world!"
   },
   "raw_body": null,
   "expect_status": 400,
   "expect_code": "model_kind_mismatch"
  },
  {
   "name": "鉴权失效",
   "method": "POST",
   "path": "/v1/embeddings",
   "auth": "invalid",
   "body": {
    "model": "embed-mini",
    "input": "Hello, world!"
   },
   "raw_body": null,
   "expect_status": 401,
   "expect_code": "invalid_api_key"
  },
  {
   "name": "鉴权失效 (Key 不存在)",
   "method": "POST",
   "path": "/v1/embeddings",
   "auth": "missing",
   "body": {
    "model": "embed-mini",
    "input": "Hello, world!"
   },
   "raw_body": null,
   "expect_status": 401,
   "expect_code": "invalid_api_key"
  },
  {
   "name": "鉴权失效 (Key 不存在，但有其他 Key)",
   "method": "POST",
   "path": "/v1/embeddings",
   "auth": "limited",
   "body": {
    "model": "embed-mini",
    "input": "Hello, world!"
   },
   "raw_body": null,
   "expect_status": 401,
   "expect_code": "invalid_api_key"
  }
 ]
}
